let panel = 'Generator';
let stageTarget = 0, stageT = 0;
let hoveredMesh = null;
let playing = false, playStart = 0;

canvas.addEventListener('pointermove', (e) => {
  const hit = _firstInteractiveHit(e);
  hoveredMesh = hit ? hit.object : null;
});
canvas.addEventListener('pointerleave', () => { hoveredMesh = null; });

const tmpC = new THREE.Color();

function paintHalf(half) {
  const active = (panel === 'Both') || (panel === half.name);
  const extraOp = active ? 1 : 0.10;
  half.extras.forEach(m => { m.opacity = extraOp; });
  half.labels.forEach(l => { l.div.style.opacity = active ? '1' : '0.16'; });

  half.stages.forEach((st, i) => {
    const reached = THREE.MathUtils.clamp(stageT - i + 1, 0, 1);
    const hot = Math.max(0, 1 - Math.abs(stageT - i));
    st.blocks.forEach(b => {
      const hovered = hoveredMesh === b.mesh;
      let op = active ? (0.28 + 0.72 * reached) : 0.09;
      if (hovered) op = Math.max(op, 0.95);
      b.mats.forEach((m, k) => {
        m.opacity = op;
        if (!b.noTint) {
          tmpC.copy(b.base[k]).lerp(HL, hot * 0.5 * (active ? 1 : 0));
          m.color.copy(tmpC);
        }
      });
      tmpC.set(0x000000);
      if (active) tmpC.lerp(HL_EDGE, hot * 0.9);
      if (hovered) tmpC.copy(HOV_EDGE);
      b.edgeMat.color.copy(tmpC);
      b.edgeMat.opacity = active ? Math.max(0.35, op) : 0.18;
    });
    st.labels.forEach(l => {
      if (!active) { l.div.style.opacity = '0.16'; return; }
      l.div.style.opacity = String(0.32 + 0.68 * reached);
      l.div.style.fontWeight = hot > 0.55 ? '700' : '400';
    });
  });
}

