    body: 'Now 32×32 with 128 channels: the square face is large, the receding depth is short.' } });
const gImg = makeBlock(genG, { cx: -1.4, w: 3.6, h: 3.6, dep: 0.06,
  front: 0xffffff, top: 0xf2f2f2, side: 0xe6e6e6, frontMap: makePhotoTexture(),
  info: { title: '64×64×3 generated image x*', tooltip: '64×64×3 output image',
    body: 'A last fractional convolution with an arctan activation gives a 64×64 image with 3 colour channels — a thin plane.' } });

[-9.9, -7.6, -6.6, -5.3, -3.5].forEach(x => groundArrow(genG, x));

/* ── middle arrow ─────────────────────────────────────────────────────────── */
makeArrow(midG, new THREE.Vector3(0.75, 1.35, 0), new THREE.Vector3(1.95, 1.35, 0), 0.2, 0.07);

/* ── DISCRIMINATOR geometry ───────────────────────────────────────────────── */
const d128 = makeBlock(disG, { cx: 2.9, w: 1.8, h: 1.8, dep: 0.65,
  info: { title: '32×32×128', tooltip: '32×32×128 — strided convolution',
    body: 'The first strided convolution halves the 64×64 input to 32×32 while raising the channel count to 128.' } });
const d256 = makeBlock(disG, { cx: 4.35, w: 0.9, h: 0.9, dep: 1.0,
  info: { title: '16×16×256', tooltip: '16×16×256 — strided convolution',
    body: 'Space halves to 16×16, channels double to 256.' } });
const d512 = makeBlock(disG, { cx: 5.55, w: 0.45, h: 0.45, dep: 1.5,
  info: { title: '8×8×512', tooltip: '8×8×512 — strided convolution',
    body: 'Space halves to 8×8, channels double to 512.' } });
const d1024 = makeBlock(disG, { cx: 6.9, w: 0.22, h: 0.22, dep: 3.4,
  info: { title: '4×4×1024', tooltip: '4×4×1024 — strided convolution',
    body: 'The deepest volume: only 4×4 in space but 1024 channels, drawn as a long low slab.' } });
const dS1 = makeBlock(disG, { cx: 8.7, w: 0.12, h: 0.12, dep: 0.12,
  front: C_CYAN, top: C_CYAN_T, side: C_CYAN_S,
  info: { title: '1×1 scalar', tooltip: '1×1 — 4×4 convolution output',
    body: 'A 4×4 convolution collapses the remaining spatial dimensions to a single number.' } });
const dS2 = makeBlock(disG, { cx: 9.3, w: 0.12, h: 0.12, dep: 0.12,
  front: C_CYAN, top: C_CYAN_T, side: C_CYAN_S,
  info: { title: 'Pr(real)', tooltip: 'sigmoid → Pr(real)',
    body: 'A sigmoid squashes the scalar into [0,1]: the probability that the input image was real rather than generated.' } });

[1.8, 3.85, 5.2, 6.6, 8.4].forEach(x => groundArrow(disG, x));
groundArrow(disG, 9.0, 0.55);

/* ── braces ───────────────────────────────────────────────────────────────── */
const braceGen = makeBrace(genG, -11.0, 0.5, 4.55, 0.22);
const braceDis = makeBrace(disG, 1.5, 9.9, 4.55, 0.22);

/* ── camera (after all geometry) ──────────────────────────────────────────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
  rollDeg: 0, heightFraction: 0.92 });

/* ── labels ───────────────────────────────────────────────────────────────── */
const labGen = L('Generator', -5.25, 5.35, 0, { fontSize: '21px' });
const labDis = L('Discriminator', 5.7, 5.35, 0, { fontSize: '21px' });

const lab100 = L('100&times;1', -10.25, 3.95, 0, { fontSize: '15px' });
const labZ = L('Latent<br>variable, <b>z</b>', -11.75, 2.55, 0, { fontSize: '15px' });

const labG1024 = L('4&times;4&times;1024', -8.95, 0.52, -3.4, { fontSize: '15px' });
const labG512 = L('8&times;8&times;512', -6.95, 0.74, -1.5, { fontSize: '15px' });
const labG256 = L('16&times;16&times;256', -5.85, 1.18, -1.0, { fontSize: '15px' });
const labG128 = L('32&times;32&times;128', -4.35, 2.10, -0.65, { fontSize: '15px' });
const labGImg = L('64&times;64&times;3', -1.85, 3.92, -0.06, { fontSize: '15px' });

const capPR = L('Project and<br>reshape', -9.85, -0.58, 0, { fontSize: '15px' });
const capFC = L('Fractional<br>convolution', -6.3, -0.58, 0, { fontSize: '15px' });
const capAT = L('arctan', -3.1, -0.48, 0, { fontSize: '15px' });

const labXor = L('<b>x</b> or <b>x</b><sup>*</sup>', 1.35, 1.72, 0, { fontSize: '15px' });

const labD128 = L('32&times;32&times;128', 3.35, 2.10, -0.65, { fontSize: '15px' });
const labD256 = L('16&times;16&times;256', 4.55, 1.18, -1.0, { fontSize: '15px' });
const labD512 = L('8&times;8&times;512', 5.6, 0.74, -1.5, { fontSize: '15px' });
const labD1024 = L('4&times;4&times;1024', 6.95, 0.52, -3.4, { fontSize: '15px' });
const labPr = L('<i>Pr</i>(real)', 9.85, 1.05, 0, { fontSize: '15px' });
const lab11 = L('1&times;1', 9.6, 0.62, 0, { fontSize: '15px' });

const capSC = L('Strided<br>convolution', 4.35, -0.58, 0, { fontSize: '15px' });
const capCC = L('4&times;4<br>convolution', 7.7, -0.58, 0, { fontSize: '15px' });
const capSig = L('sigmoid', 9.55, -0.48, 0, { fontSize: '15px' });

/* ── half bookkeeping ─────────────────────────────────────────────────────── */
function matsOf(obj) {
  const out = [];
  obj.traverse(o => {
    if (o.material) (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => out.push(m));
  });
  return out;
}

const genExtraMats = matsOf(genG).filter(m => !blocksAll.some(b => b.mats.includes(m)));
const disExtraMats = matsOf(disG).filter(m => !blocksAll.some(b => b.mats.includes(m)));
const genEdgeMats = [], disEdgeMats = [];

const genHalf = {
  name: 'Generator',
  extras: genExtraMats,
  labels: [labGen, lab100, labZ, capPR, capFC, capAT],
  stages: [
    { blocks: [latBot, latTop], labels: [lab100, labZ], name: '100 × 1', op: 'Latent variable z (noise input)' },
    { blocks: [g1024], labels: [labG1024], name: '4 × 4 × 1024', op: 'Project and reshape' },
    { blocks: [g512], labels: [labG512], name: '8 × 8 × 512', op: 'Fractional convolution' },
    { blocks: [g256], labels: [labG256], name: '16 × 16 × 256', op: 'Fractional convolution' },
    { blocks: [g128], labels: [labG128], name: '32 × 32 × 128', op: 'Fractional convolution' },
    { blocks: [gImg], labels: [labGImg], name: '64 × 64 × 3', op: 'Fractional convolution + arctan → x*' }
  ]
};
const disHalf = {
  name: 'Discriminator',
  extras: disExtraMats,
  labels: [labDis, capSC, capCC, capSig],
  stages: [
    { blocks: [], labels: [], name: '64 × 64 × 3', op: 'Input image x (real) or x* (generated)' },
    { blocks: [d128], labels: [labD128], name: '32 × 32 × 128', op: 'Strided convolution' },
    { blocks: [d256], labels: [labD256], name: '16 × 16 × 256', op: 'Strided convolution' },
    { blocks: [d512], labels: [labD512], name: '8 × 8 × 512', op: 'Strided convolution' },
    { blocks: [d1024], labels: [labD1024], name: '4 × 4 × 1024', op: 'Strided convolution' },
    { blocks: [dS1, dS2], labels: [lab11, labPr], name: '1 × 1', op: '4×4 convolution, then sigmoid → Pr(real)' }
  ]
};
genHalf.stages.forEach(s => s.labels.forEach(l => genHalf.labels.push(l)));
disHalf.stages.forEach(s => s.labels.forEach(l => disHalf.labels.push(l)));
const midMats = matsOf(midG);

/* ── state + update ───────────────────────────────────────────────────────── */
let panel = 'Generator';
let stageTarget = 0, stageT = 0;
let hoveredMesh = null;
let playing = false, playStart = 0;

canvas.addEventListener('pointermove', (e) => {
  const hit = _firstInteractiveHit(e);
  hoveredMesh = hit ? hit.object : null;
});
canvas.addEventListener('pointerleave', () => { hoveredMesh = null; });

const tmpC = new THREE.Color();

function paintHalf(half) {
  const active = (panel === 'Both') || (panel === half.name);
  const extraOp = active ? 1 : 0.10;
  half.extras.forEach(m => { m.opacity = extraOp; });
  half.labels.forEach(l => { l.div.style.opacity = active ? '1' : '0.16'; });

  half.stages.forEach((st, i) => {
    const reached = THREE.MathUtils.clamp(stageT - i + 1, 0, 1);
    const hot = Math.max(0, 1 - Math.abs(stageT - i));
    st.blocks.forEach(b => {
      const hovered = hoveredMesh === b.mesh;
      let op = active ? (0.28 + 0.72 * reached) : 0.09;
      if (hovered) op = Math.max(op, 0.95);
      b.mats.forEach((m, k) => {
        m.opacity = op;
        if (!b.noTint) {
          tmpC.copy(b.base[k]).lerp(HL, hot * 0.5 * (active ? 1 : 0));
          m.color.copy(tmpC);
        }
      });
      tmpC.set(0x000000);
      if (active) tmpC.lerp(HL_EDGE, hot * 0.9);
      if (hovered) tmpC.copy(HOV_EDGE);
      b.edgeMat.color.copy(tmpC);
      b.edgeMat.opacity = active ? Math.max(0.35, op) : 0.18;
    });
    st.labels.forEach(l => {
      if (!active) { l.div.style.opacity = '0.16'; return; }
      l.div.style.opacity = String(0.32 + 0.68 * reached);
      l.div.style.fontWeight = hot > 0.55 ? '700' : '400';
    });
  });
}

function updateVisuals() {
  paintHalf(genHalf);
  paintHalf(disHalf);
  const midOn = (panel === 'Both') || (panel === 'Discriminator' && stageT < 1.5) || (panel === 'Generator' && stageT > 4.5);
  const mo = midOn ? 1 : 0.18;
  midMats.forEach(m => { m.opacity = mo; });
  labXor.div.style.opacity = String(midOn ? 1 : 0.2);
}

const stageOut = document.getElementById('stageOut');
const stageInfo = document.getElementById('stageInfo');
const stageSlider = document.getElementById('stageSlider');

function refreshReadout() {
  const i = Math.max(0, Math.min(5, Math.round(stageT)));
  stageOut.textContent = i;
  stageSlider.value = String(i);
  const halves = panel === 'Discriminator' ? [disHalf] : panel === 'Generator' ? [genHalf] : [genHalf, disHalf];
  stageInfo.innerHTML = halves.map(h =>
    `<b>${h.name}</b> · stage ${i}<br><span style="font-family:${SERIF}">${h.stages[i].name}</span> — ${h.stages[i].op}`
  ).join('<div style="height:4px"></div>');
}

/* ── controls ─────────────────────────────────────────────────────────────── */
const btnGen = document.getElementById('btnGen');
const btnDis = document.getElementById('btnDis');
const btnBoth = document.getElementById('btnBoth');
function setPanel(p) {
  panel = p;
  btnGen.classList.toggle('active', p === 'Generator');
  btnDis.classList.toggle('active', p === 'Discriminator');
  btnBoth.classList.toggle('active', p === 'Both');
  refreshReadout();
}
btnGen.addEventListener('click', () => setPanel('Generator'));
btnDis.addEventListener('click', () => setPanel('Discriminator'));
btnBoth.addEventListener('click', () => setPanel('Both'));

const btnPlay = document.getElementById('playForward');
stageSlider.addEventListener('input', () => {
  playing = false; btnPlay.textContent = '▶ Play forward pass';
  stageTarget = parseFloat(stageSlider.value);
  refreshReadout();
});

btnPlay.addEventListener('click', () => {
  if (playing) { playing = false; btnPlay.textContent = '▶ Play forward pass'; return; }
  playing = true; btnPlay.textContent = '❚❚ Pause';
  stageT = 0; stageTarget = 0; playStart = performance.now();
});

/* ── guided tour ──────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'Latent variable z', n: 'The generator starts from a 100×1 vector of noise — a single thin column, no spatial structure at all.', p: 'Generator', s: 0 },
  { t: 'Project and reshape', n: 'A linear projection reshapes the 100 numbers into a 4×4×1024 volume: tiny in space, enormously deep in channels — drawn as a long flat slab.', p: 'Generator', s: 1 },
  { t: 'Fractional convolutions upsample', n: 'Each fractionally strided convolution doubles the spatial size and halves the channels: 8×8×512, then 16×16×256, then 32×32×128 — the face grows as the depth shrinks.', p: 'Generator', s: 4 },
  { t: 'arctan to the image', n: 'A final fractional convolution plus arctan produces a 64×64×3 image — a thin plane with three colour channels.', p: 'Generator', s: 5 },
  { t: 'Hand the image to the discriminator', n: 'Either a real image x or the generated x* enters the discriminator, which runs the same pyramid in reverse using strided convolutions.', p: 'Discriminator', s: 1 },
  { t: 'Down to a single probability', n: 'Strided convolutions shrink 32×32×128 → 16×16×256 → 8×8×512 → 4×4×1024; a 4×4 convolution collapses space to 1×1 and a sigmoid outputs Pr(real).', p: 'Discriminator', s: 5 },
  { t: 'The mirrored pair', n: 'Seen together, the two halves are symmetric funnels: the generator widens space and narrows depth, the discriminator does the exact reverse.', p: 'Both', s: 5 }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  playing = false; btnPlay.textContent = '▶ Play forward pass';
  setPanel(st.p);
  stageTarget = st.s;
  stepTitle.textContent = (stepIdx + 1) + '. ' + st.t;
  stepText.textContent = st.n;
  refreshReadout();
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── own animation loop for the stage tween ───────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  if (playing) {
    const e = (performance.now() - playStart) / 1000;
    stageT = Math.min(5, e / 1.05);
    stageTarget = stageT;
    if (stageT >= 5) { playing = false; btnPlay.textContent = '▶ Play forward pass'; }
    refreshReadout();
  } else if (Math.abs(stageT - stageTarget) > 0.001) {
    stageT += (stageTarget - stageT) * 0.16;
    if (Math.abs(stageT - stageTarget) <= 0.001) stageT = stageTarget;
    refreshReadout();
  }
  updateVisuals();
}
goToStep(0);
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

