});
canvas.addEventListener('pointerleave', () => { hoveredMesh = null; });

const tmpC = new THREE.Color();

function paintHalf(half) {
  const active = (panel === 'Both') || (panel === half.name);
  const extraOp = active ? 1 : 0.10;
  half.extras.forEach(m => { m.opacity = extraOp; });
  half.labels.forEach(l => { l.div.style.opacity = active ? '1' : '0.15'; });

  half.stages.forEach((st, i) => {
    const reached = THREE.MathUtils.clamp(stageT - i + 1, 0, 1);
    const hot = Math.max(0, 1 - Math.abs(stageT - i));
    st.blocks.forEach(b => {
      const hovered = hoveredMesh === b.mesh;
      // printed-solid baseline: everything is opaque; only the inactive half fades.
      let op = active ? (0.82 + 0.18 * reached) : 0.09;
      if (hovered) op = 1;
      b.mats.forEach((m, k) => {
        m.opacity = op;
        if (!b.noTint) {
          // hue-preserving highlight: cyan stays cyan, orange stays orange
          tmpC.copy(b.base[k]).lerp(b.hl[k], active ? hot : 0);
          m.color.copy(tmpC);
        }
      });
      if (hovered) b.edgeMat.color.copy(HOV_EDGE);
      else b.edgeMat.color.set(0x000000);
      b.edgeMat.opacity = active ? 1 : 0.14;
    });
    st.labels.forEach(l => {
      if (!active) { l.div.style.opacity = '0.15'; return; }
      l.div.style.opacity = String(0.55 + 0.45 * reached);
      l.div.style.fontWeight = hot > 0.55 ? '700' : '400';
    });
  });
}

