}

function hlOf(c) { const o = c.clone(); o.offsetHSL(0, 0.16, 0.10); return o; }

function makeBlock(parent, o) {
  const w = o.w, h = o.h, dep = o.dep, baseY = o.baseY || 0;
  const geo = new THREE.BoxGeometry(w, h, dep);
  const mk = (c) => new THREE.MeshBasicMaterial({
    color: new THREE.Color(c), side: THREE.DoubleSide, transparent: true, opacity: 1,
    polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  });
  const front = o.front ?? C_FRONT, top = o.top ?? C_TOP, side = o.side ?? C_SIDE;
  const mats = [mk(side), mk(side), mk(top), mk(side), mk(front), mk(front)];
  if (o.frontMap) {
    mats[4] = new THREE.MeshBasicMaterial({
      map: o.frontMap, side: THREE.DoubleSide, transparent: true, opacity: 1,
      polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
    });
  }
  const mesh = new THREE.Mesh(geo, mats);
  mesh.position.set(o.cx, baseY + h / 2, -dep / 2);
  const edgeMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 1 });
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo), edgeMat));
  parent.add(mesh);
  const base = mats.map(m => m.color.clone());
  const rec = { mesh, mats, edgeMat, base, hl: base.map(hlOf), noTint: !!o.frontMap };
  if (o.info) registerInteractive(mesh, o.info);
  blocksAll.push(rec);
  return rec;
}

function makeArrow(parent, from, to, headLen, headR, shaftR) {
  headLen = headLen || 0.42; headR = headR || 0.095; shaftR = shaftR || 0.028;
  const g = new THREE.Group();
  const dv = new THREE.Vector3().subVectors(to, from);
  const len = dv.length();
  const dir = dv.clone().normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  const mat = () => new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, side: THREE.DoubleSide });
  const shaftLen = Math.max(0.02, len - headLen * 0.85);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, shaftLen, 10), mat());
  shaft.quaternion.copy(q);
  shaft.position.copy(from).addScaledVector(dir, shaftLen / 2);
  g.add(shaft);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 16), mat());
  cone.quaternion.copy(q);
  cone.position.copy(to).addScaledVector(dir, -headLen / 2);
  g.add(cone);
  parent.add(g);
  return g;
}

/* ground arrow: runs along -Z → up-right along the oblique depth diagonal */
function groundArrow(parent, x, len) {
  len = len || 1.70;
  return makeArrow(parent,
    new THREE.Vector3(x, -0.30, 0.30),
    new THREE.Vector3(x, -0.30, 0.30 - len));
}

function makeBrace(parent, x0, x1, y, r) {
  const pts = [], mid = (x0 + x1) / 2, N = 14;
  const arc = (cx, cy, a0, a1) => {
    for (let i = 0; i <= N; i++) {
      const a = a0 + (a1 - a0) * i / N;
      pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0));
    }
  };
  arc(x0 + r, y, Math.PI, Math.PI / 2);
  pts.push(new THREE.Vector3(mid - r, y + r, 0));
  arc(mid - r, y + 2 * r, -Math.PI / 2, 0);
  arc(mid + r, y + 2 * r, Math.PI, Math.PI * 1.5);
  pts.push(new THREE.Vector3(x1 - r, y + r, 0));
  arc(x1 - r, y, Math.PI / 2, 0);
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000, transparent: true }));
  parent.add(line);
  return line;
}

/* ── blurry interior photo texture (fills the whole face — no grey backing) ── */
function makePhotoTexture() {
  const S = 24;
  const lo = document.createElement('canvas'); lo.width = lo.height = S;
  const g = lo.getContext('2d');
  const R = (x, y, w, h, c) => { g.fillStyle = c; g.fillRect(x, y, w, h); };
  R(0, 0, S, S, '#cdc6b8');            // back wall
  R(0, 0, S, 5.5, '#eae7e0');          // ceiling
  R(0, 16.5, S, 7.5, '#a8a092');       // floor
  R(0, 20, S, 4, '#8e8778');           // nearer floor
  R(0, 16.2, S, 0.8, '#7c7568');       // floor/wall join
  R(14.5, 4, 8.5, 10.5, '#fbfaf5');    // bright window
  R(14.5, 4, 8.5, 1.1, '#cdc6b6');     // window head
  R(18.4, 4, 0.9, 10.5, '#cfc8ba');    // mullion
  R(1, 5, 3.4, 11.5, '#3a3f45');       // dark cabinet
  R(5.2, 6.2, 1.9, 10.3, '#6b6154');   // wooden post
  R(8.4, 4.2, 3.2, 9.0, '#4a4e51');    // dark panel
  R(11.8, 9.5, 2.3, 7.0, '#e7e5dd');   // white object
  R(6.4, 13.5, 4.2, 3.0, '#bdb7a8');   // pale box
  R(16.3, 16.8, 4.2, 4.2, '#ddb038');  // warm yellow object
  R(20.8, 6, 2.2, 6, '#f6f4ec');       // window glare

  const N = 64;
  const c = document.createElement('canvas'); c.width = c.height = N;
  const ctx = c.getContext('2d');
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(lo, 0, 0, N, N);
  // extra blur: downsample then upsample twice, blended over the sharper pass
  const tmp = document.createElement('canvas'); tmp.width = tmp.height = 13;
  const tc = tmp.getContext('2d'); tc.imageSmoothingEnabled = true;
  tc.drawImage(c, 0, 0, 13, 13);
  ctx.globalAlpha = 0.75;
  ctx.drawImage(tmp, 0, 0, N, N);
  ctx.globalAlpha = 1;
  tc.clearRect(0, 0, 13, 13); tc.drawImage(c, 0, 0, 13, 13);
  ctx.globalAlpha = 0.45;
  ctx.drawImage(tmp, 0, 0, N, N);
  ctx.globalAlpha = 1;
  // faint film grain
  const id = ctx.getImageData(0, 0, N, N), dd = id.data;
  for (let i = 0; i < dd.length; i += 4) {
    const n = (Math.random() - 0.5) * 14;
    dd[i] = Math.max(0, Math.min(255, dd[i] + n));
    dd[i + 1] = Math.max(0, Math.min(255, dd[i + 1] + n));
    dd[i + 2] = Math.max(0, Math.min(255, dd[i + 2] + n));
  }
  ctx.putImageData(id, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearFilter;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

